import torch
torch.manual_seed(0)
features=torch.randn(4,3)
edges={"supplier":[(0,1),(2,1)],"industry":[(3,1)]}
layers={k:torch.nn.Linear(3,2,bias=False) for k in edges}
out=torch.zeros(2)
for relation,edge_list in edges.items():
    out=out+torch.stack([layers[relation](features[u]) for u,v in edge_list if v==1]).mean(0)
print("Target heterogeneous messages:",out)

edges=[("A","B",2023,2025),("B","C",2025,2028),("A","C",2024,2027)]
def snapshot(year):
    return [(u,v) for u,v,start,end in edges if start<=year<end]
for year in [2023,2024,2025]:
    print(year,snapshot(year))
